define(["core/str"],function(Str){const formatTime=seconds=>{const s=Math.max(0,Math.round(Number(seconds||0)));const h=Math.floor(s/3600);const m=Math.floor(s%3600/60);const r=s%60;return(h?String(h).padStart(2,"0")+":":"")+String(m).padStart(2,"0")+":"+String(r).padStart(2,"0")};const player=()=>window.modVideoDebatePlayer||null;const initEvidenceForm=(region,strings)=>{const form=region.closest("form");if(!form){return}const hidden=form.querySelector('input[name="evidencejson"]');if(!hidden){return}let evidence=[];let intervalStart=null;const controls=document.createElement("div");controls.className="border rounded p-3 mb-3";const title=document.createElement("div");title.className="fw-bold mb-2";title.textContent=strings.evidencetitle;const point=document.createElement("button");point.type="button";point.className="btn btn-outline-primary btn-sm me-2";point.textContent=strings.addcurrentmoment;const interval=document.createElement("button");interval.type="button";interval.className="btn btn-outline-secondary btn-sm";interval.textContent=strings.startinterval;const list=document.createElement("div");list.className="mt-3";controls.append(title,point,interval,list);region.appendChild(controls);const sync=()=>{hidden.value=JSON.stringify(evidence)};const render=()=>{list.textContent="";evidence.forEach((item,index)=>{const row=document.createElement("div");row.className="d-flex align-items-center gap-2 mb-1";const label=document.createElement("span");label.className="badge bg-light text-dark border";label.textContent=formatTime(item.start)+(item.end>item.start+.5?"–"+formatTime(item.end):"");const input=document.createElement("input");input.type="text";input.className="form-control form-control-sm";input.placeholder=strings.evidencedescription;input.value=item.label||"";input.addEventListener("input",()=>{evidence[index].label=input.value;sync()});const remove=document.createElement("button");remove.type="button";remove.className="btn btn-sm btn-link text-danger";remove.textContent=strings.remove;remove.addEventListener("click",()=>{evidence.splice(index,1);sync();render()});row.append(label,input,remove);list.appendChild(row)});sync()};point.addEventListener("click",()=>{const p=player();if(!p){return}p.getCurrentTime().then(time=>{evidence.push({start:time,end:time,label:""});render()})});interval.addEventListener("click",()=>{const p=player();if(!p){return}p.getCurrentTime().then(time=>{if(intervalStart===null){intervalStart=time;interval.textContent=strings.finishinterval;interval.classList.add("btn-warning")}else{const start=Math.min(intervalStart,time);const end=Math.max(intervalStart,time);evidence.push({start:start,end:end,label:""});intervalStart=null;interval.textContent=strings.startinterval;interval.classList.remove("btn-warning");render()}})})};const buildTimeline=()=>{const timeline=document.querySelector('[data-region="evidence-timeline"]');const p=player();if(!timeline||!p){return}p.getDuration().then(duration=>{if(!duration){return}timeline.textContent="";document.querySelectorAll('[data-action="seek-evidence"]').forEach(button=>{const time=Number(button.dataset.time||0);const marker=document.createElement("button");marker.type="button";marker.className="videodebate-marker";marker.style.left=Math.min(100,Math.max(0,time/duration*100))+"%";marker.title=formatTime(time);marker.addEventListener("click",()=>p.seek(time));timeline.appendChild(marker)})})};return{init:function(){Str.get_strings([{key:"evidencetitle",component:"videodebate"},{key:"addcurrentmoment",component:"videodebate"},{key:"startinterval",component:"videodebate"},{key:"finishinterval",component:"videodebate"},{key:"evidencedescription",component:"videodebate"},{key:"remove",component:"videodebate"}]).then(values=>{const strings={evidencetitle:values[0],addcurrentmoment:values[1],startinterval:values[2],finishinterval:values[3],evidencedescription:values[4],remove:values[5]};document.querySelectorAll('[data-region="evidence-form"]').forEach(region=>initEvidenceForm(region,strings))});document.addEventListener("click",event=>{const button=event.target.closest('[data-action="seek-evidence"]');if(!button||!player()){return}event.preventDefault();player().seek(Number(button.dataset.time||0));const video=document.getElementById("videodebate-player");if(video){video.scrollIntoView({behavior:"smooth",block:"center"})}});document.addEventListener("videodebate:playerready",buildTimeline,{once:true});if(player()){buildTimeline()}}}});